s_magic":true},{"id":"plant_m009","category":"plant","name":"Şafak Kapısı Düğümü","kind":"Sarmaşık","rarity":"Çok nadir","image":"seed_m009.webp","description":"Şafak Kapısı Düğümü, sıcak koru sınırı içinde bulunur. Yaprak boğumları şafakla birlikte açılır, geceleri kapanır.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: sıcak koru sınırı; Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m010","category":"plant","name":"Uyku Çanı","kind":"Çiçek","rarity":"Çok nadir","image":"seed_m010.webp","description":"Uyku Çanı, nemli patika açıklığı içinde bulunur. Aşağı bakan soluk çiçekleri gece ağır bir koku yayar.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: nemli patika açıklığı; Gümüş Sis döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m011","category":"plant","name":"Gökyüzü Darısı","kind":"Tahıl","rarity":"Çok nadir","image":"seed_m011.webp","description":"Gökyüzü Darısı, yüksek ve rüzgârlı çayır içinde bulunur. Tanelerinin kabuğunda ince yıldız çizgileri bulunur.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: yüksek ve rüzgârlı çayır; Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m012","category":"plant","name":"Eşik Ağacı","kind":"Ağaç","rarity":"Çok nadir","image":"seed_m012.webp","description":"Eşik Ağacı, sisli eski orman sınırı içinde bulunur. Gövdesi çatallanır; yeni filizleri iki farklı mevsimde de yeşerir.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: sisli eski orman sınırı; Gümüş Sis,Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m013","category":"plant","name":"Ay Camı Armudu","kind":"Ağaç","rarity":"Çok nadir","image":"seed_m013.webp","description":"Ay Camı Armudu, dere kenarındaki yaşlı koru içinde bulunur. İnce kabuklu iri armutları sisli gecede yarı saydam görünür.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: dere kenarındaki yaşlı koru; Gümüş Sis döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m014","category":"plant","name":"Kızıl Yıldız Elması","kind":"Ağaç","rarity":"Çok nadir","image":"seed_m014.webp","description":"Kızıl Yıldız Elması, yüksek ve açık meyve bahçesi içinde bulunur. Beş köşeli çiçek izleri taşıyan koyu kızıl elmaları dallarında olgunlaşır.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: yüksek ve açık meyve bahçesi; Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m015","category":"plant","name":"Serap İnciri","kind":"Ağaç","rarity":"Çok nadir","image":"seed_m015.webp","description":"Serap İnciri, sıcak kayalık vadi içinde bulunur. Geniş yapraklarının altında damla biçimli çizgili incir salkımları yetişir.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: sıcak kayalık vadi; Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m016","category":"plant","name":"Ay Sis Böğürtleni","kind":"Çalı","rarity":"Çok nadir","image":"seed_m016.webp","description":"Ay Sis Böğürtleni, ıslak çalılık ve orman kıyısı içinde bulunur. Dikenli dallarında çiy altında parlayan koyu renkli böğürtlen kümeleri taşır.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: ıslak çalılık ve orman kıyısı; Gümüş Sis döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m017","category":"plant","name":"Melek Narısı","kind":"Çalı","rarity":"Çok nadir","image":"seed_m017.webp","description":"Melek Narısı, rüzgârdan korunaklı taş teras içinde bulunur. Dallarından sarkan küçük kabuklu narların taçları altı sivri dişlidir.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: rüzgârdan korunaklı taş teras; Yıldız Dönemi döneminde ortaya çıkar.","is_magic":true},{"id":"plant_m018","category":"plant","name":"Gümüş Çiy Üzümü","kind":"Sarmaşık","rarity":"Çok nadir","image":"seed_m018.webp","description":"Gümüş Çiy Üzümü, yaşlı söğütlere sarılan nemli kıyı içinde bulunur. Yapraklarının arasından ağır, yuvarlak, çiy kaplı üzüm salkımları iner.","uses":"Manevi etki için otomatik kural yok; DM araştırmayla anlamını açar.","conditions":"Doğal yaşam: yaşlı söğütlere sarılan nemli kıyı; Gümüş Sis döneminde ortaya çıkar.","is_magic":true}]'::jsonb) as x(
  id text,category text,name text,kind text,rarity text,image text,description text,uses text,
  conditions text,growth_days integer,soils text[],seasons text[],min_sun smallint,
  min_humidity smallint,max_humidity smallint,min_temperature smallint,max_temperature smallint,
  plant_id text,yield_resource text,is_magic boolean)
on conflict(id) do update set
  name=excluded.name,kind=excluded.kind,rarity=excluded.rarity,image=excluded.image,
  description=excluded.description,uses=excluded.uses,conditions=excluded.conditions,
  growth_days=excluded.growth_days,soils=excluded.soils,seasons=excluded.seasons,
  min_sun=excluded.min_sun,min_humidity=excluded.min_humidity,max_humidity=excluded.max_humidity,
  min_temperature=excluded.min_temperature,max_temperature=excluded.max_temperature,
  plant_id=excluded.plant_id,yield_resource=excluded.yield_resource,is_magic=excluded.is_magic;

update fnf_private.codex_catalog set image=id||'.webp' where id in ('plant_01','plant_002','plant_003','plant_004','plant_005','plant_006','plant_007','plant_008','plant_009','plant_010','plant_011','plant_012','plant_013','plant_014','plant_015','plant_016','plant_017','plant_018','plant_019','plant_020','plant_021','plant_022','plant_023','plant_024','plant_025','plant_026','plant_027','plant_028','plant_029','plant_030','plant_031','plant_032','plant_033','plant_034','plant_051','plant_052','plant_053','plant_054','plant_055','plant_056','plant_057','plant_058','plant_059','plant_060','plant_081');
update fnf_private.codex_catalog set conditions=replace(conditions,
  'Üretim ve yetiştirme kuralı henüz yok.','Ekim koşulları eşleşen tohum kaydında bulunur.')
where category='plant' and id not like 'plant_m%';
update fnf_private.codex_catalog set uses='Meyvesi hasatta yiyecek stoğuna girer. Özel etkisini DM keşifle açar.'
where category='plant' and id between 'plant_051' and 'plant_060';

update fnf_private.codex_catalog set plant_id='plant_081',yield_resource='grain' where id='seed_01';
update fnf_private.codex_catalog set plant_id='plant_051',yield_resource='food' where id='seed_02';
update fnf_private.codex_catalog set plant_id='plant_071',yield_resource='herbs' where id='seed_03';

insert into public.fnf_codex_reveals(room_id,entry_id)
select r.id,c.id from public.fnf_rooms r cross join fnf_private.codex_catalog c
on conflict(room_id,entry_id) do nothing;
insert into public.fnf_seed_stock(room_id,seed_id,amount)
select r.id,c.id,0 from public.fnf_rooms r cross join fnf_private.codex_catalog c
where c.category='seed' on conflict(room_id,seed_id) do nothing;
